package com.az.scicalc;
import java.math.BigInteger;
/** Signed 64-bit calculator: arithmetic and bitwise operations use two's complement. */
final class BaseExpression {
 final String s;final int radix;int i,bits=64;
 BaseExpression(String s,int radix){this.s=s.replace("×","*").replace("÷","/").replace("−","-").replaceAll("(?i)\\band\\b","&").replaceAll("(?i)\\bor\\b","|").replaceAll("(?i)\\bxor\\b","^").replaceAll("(?i)\\bnot\\b","~").replaceAll("(?i)\\bmod\\b","%").replaceAll("(?i)\\bnand\\b","nand").replaceAll("(?i)\\bnor\\b","nor").replaceAll("(?i)\\bxnor\\b","xnor");this.radix=radix;}
 static long evaluate(String s,int radix){BaseExpression p=new BaseExpression(s,radix);long v=p.or();p.skip();if(p.i!=p.s.length())throw new IllegalArgumentException("无法识别位置 "+(p.i+1));return v;}
 static long evaluate(String s,int radix,int bits){BaseExpression p=new BaseExpression(s,radix);p.bits=bits;long v=p.or();p.skip();if(p.i!=p.s.length())throw new IllegalArgumentException("无法识别位置 "+(p.i+1));return v;}
 void skip(){while(i<s.length()&&Character.isWhitespace(s.charAt(i)))i++;}boolean take(String v){skip();if(s.startsWith(v,i)){i+=v.length();return true;}return false;}
 long or(){long n=xor();while(true){if(take("|"))n|=xor();else if(take("nor"))n=~(n|xor());else return n;}}long xor(){long n=and();while(true){if(take("^"))n^=and();else if(take("xnor"))n=~(n^and());else return n;}}long and(){long n=shift();while(true){if(take("&"))n&=shift();else if(take("nand"))n=~(n&shift());else return n;}}
 long shift(){long n=sum();while(true){if(take("<<"))n<<=sum();else if(take(">>>"))n>>>=sum();else if(take(">>"))n>>=sum();else return n;}}
 long sum(){long n=product();while(true){if(take("+"))n+=product();else if(take("-"))n-=product();else return n;}}
 long product(){long n=power();while(true){if(take("*"))n*=power();else if(take("/"))n/=power();else if(take("%"))n%=power();else return n;}}
 long power(){long n=atom();if(take("**")){long exponent=power();if(exponent<0)throw new IllegalArgumentException("整数幂需要非负指数");long result=1;while(exponent>0){if((exponent&1)!=0)result*=n;n*=n;exponent>>>=1;}return result;}return n;}
 long rotate(long n,long shift,boolean left){int k=Math.floorMod((int)shift,bits);if(bits==64)return left?Long.rotateLeft(n,k):Long.rotateRight(n,k);long mask=(1L<<bits)-1;n&=mask;return (left?(n<<k)|(n>>>(bits-k)):(n>>>k)|(n<<(bits-k)))&mask;}
 long atom(){if(take("-"))return -atom();if(take("+"))return atom();if(take("~"))return ~atom();if(take("(")){long n=or();if(!take(")"))throw new IllegalArgumentException("缺少右括号");return n;}skip();java.util.regex.Matcher fn=java.util.regex.Pattern.compile("([A-Za-z]+)\\(").matcher(s.substring(i));if(fn.lookingAt()){String name=fn.group(1).toLowerCase(java.util.Locale.ROOT);i+=fn.end();long a=or(),b=0;boolean pair=take(",");if(pair)b=or();if(!take(")"))throw new IllegalArgumentException("缺少右括号");switch(name){case "sqrt":if(a<0)throw new IllegalArgumentException("负数不能开平方");return (long)Math.sqrt(a);case "cbrt":return (long)Math.cbrt(a);case "root":if(!pair||a<=0)throw new IllegalArgumentException("Root(次数,数值)");return (long)Math.pow(b,1d/a);case "abs":return Math.abs(a);case "rol":case "ror":if(!pair)throw new IllegalArgumentException("旋转需要数值和位数");return rotate(a,b,name.equals("rol"));case "gcd":return BigInteger.valueOf(a).gcd(BigInteger.valueOf(b)).longValue();case "lcm":long gcd=BigInteger.valueOf(a).gcd(BigInteger.valueOf(b)).longValue();return gcd==0?0:Math.abs(a/gcd*b);case "ceil":case "floor":return a;case "randint":if(!pair||b<a||b-a==Long.MAX_VALUE)throw new IllegalArgumentException("随机范围无效");return a+java.util.concurrent.ThreadLocalRandom.current().nextLong(b-a+1);default:throw new IllegalArgumentException("未知整数函数："+name);}}int start=i;while(i<s.length()&&Character.digit(s.charAt(i),radix)>=0)i++;if(i==start)throw new IllegalArgumentException("请填写 "+radix+" 进制整数");BigInteger n=new BigInteger(s.substring(start,i),radix);if(n.bitLength()>64)throw new IllegalArgumentException("整数超过 64 位");return n.longValue();}
 static String format(long value,int radix){return radix==10?Long.toString(value):Long.toUnsignedString(value,radix).toUpperCase(java.util.Locale.ROOT);}
}
